def checkValid(matrix):
    n = len(matrix)

    # Check each row
    for row in range(n):
        seen = [False] * n
        for col in range(n):
            val = matrix[row][col]
            # Values must be in the range 1..n
            if not (1 <= val <= n):
                return False
            if seen[val - 1]:
                # Duplicate in the row
                return False
            seen[val - 1] = True

    # Check each column
    for col in range(n):
        seen = [False] * n
        for row in range(n):
            val = matrix[row][col]
            if seen[val - 1]:
                # Duplicate in the column
                return False
            seen[val - 1] = True

    return True
